cc.Class({
    extends: cc.Component,

    properties: {
        canTouch:false,
        spine:sp.Skeleton,
        spineWin:sp.Skeleton,
        _id:0,
        _handler:null,
        _jpType:0,
        _isLoaded:false,
    },

    onLoad() {
        this.canTouch = false;
        this.spine = this.node.getChildByName("spine").getComponent(sp.Skeleton);
        this.spineWin = this.node.getChildByName("spine_win").getComponent(sp.Skeleton);
        this.node.on(cc.Node.EventType.TOUCH_END, ()=>{
            if(this.canTouch) {
                this._handler(this.id);
            }
        })
        this._isLoaded = true;
        this.reset();
    },

    reset() {
        if(this._isLoaded) {
            this.canTouch = true;
            this.spineWin.node.active = false;
            this.setState(1)
        }
    },

    init(id, handler) {
        this.id = id;
        this._handler = handler;
    },

    /**
     * state 1:idle 2:gray 3:result
     */
    setState(state, jpType) {
        state = state || 1;
        jpType = jpType || 1;
        this._jpType = jpType;
        let cfg = {
            [1]:{aniName:"zhuzi_idle", loop:true, canTouch:true},
            [2]:{aniName:"zhuzi_hui", loop:false, canTouch:false},
            [3]:{aniName:"zhuzi_click", loop:false, canTouch:false}
        }[state];
        let skinName = {
            [1]:"Mini",
            [2]:"Minor",
            [3]:"Major",
            [4]:"Grand",
        }[jpType];
        this.spine.setSkin(skinName)
        this.spine.setAnimation(0, cfg.aniName, cfg.loop);
        this.canTouch = cfg.canTouch;
    },

    /**
     * 播放中加那个动画
     */
    playWin() {
        this.spineWin.node.active = true;
        this.spineWin.setAnimation(0, `glow${this._jpType}b`, true);
    }
});
