/**
 * 游戏流辅助类
 */
cc.Class({
    extends: cc.Component,

    /**
     * 进入房间
     */
    async enterRoom() {
        await this.enterWheelGame();
        let rest = cc.vv.gameData.GetFreeTime()
        if(rest > 0){
            let nTotal = cc.vv.gameData.GetTotalFreeWin()
            SlotsFacade.bottomCmp.SetWin(nTotal);
            await this.enterFreeGame(true);
        }
        await this.enterPickGame();
        SlotsFacade.slots.CanDoNextRound(); // todo
    },

    /**
     * 开始移动
     */
    async startMove() {
        SlotsFacade.freeGame.startMove();
    },

    /**
     * 收到spin消息
     * @param {*} msg
     */
    async onSpinMsg(msg) {
        await SlotsFacade.freeGame.onSpinMsg();
        SlotsFacade.slots._gameInfo = msg;
        let cards = msg.resultCards;
        SlotsFacade.slots.SetSlotsResult(cards);
        SlotsFacade.slots.SetReelStateInfo(cards);
    },

    /**
     * 旋转结束
     */
    async spinEnd() {
        await SlotsFacade.freeGame.spinEnd();
        // 显示中奖路线
        SlotsFacade.slots.ShowWinTrace();
        await this.collectEnergy();
        // 收集能量
        // 更新金币
        if (cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()) {
            await SlotsFacade.freeGame.settlementRound();
        }else {
            let nWin = cc.vv.gameData.GetGameWin();
            let nTotal = nWin;
            await new Promise(res=>{
                SlotsFacade.slots.ShowBottomWin(nWin,nTotal,true, res);
            });
        }
        await this.enterPickGame();
        await this.enterWheelGame();
        // 控制按钮
        if (SlotsFacade.dm.isTriggerFree()) {
            SlotsFacade.soundMgr.playEffect("vo_free");
            SlotsFacade.slots.Backup();
            await this.enterFreeGame();
        } else if (SlotsFacade.dm.isLastEndFree()) {
            SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
            await SlotsFacade.freeGame.settlementTotal();
            await SlotsFacade.popup.showWinGold(SlotsFacade.dm.GetGameTotalFreeWin());
            await SlotsFacade.mainPanel.showSceneTransition(1);
            SlotsFacade.slots.Resume();
            await SlotsFacade.freeGame.exit();
            await this.enterNormalGame();
        }
        SlotsFacade.slots.CanDoNextRound(); // todo
    },

    /**
     * 进入免费游戏
     */
    async enterFreeGame(isReconnect) {
        SlotsFacade.topCmp.SetBackLobby(false);
        SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
        SlotsFacade.mainPanel.showBg(1);
        SlotsFacade.soundMgr.playFreeBgm();
        SlotsFacade.bottomCmp.node.getChildByName("totalBetBg").active = true;
        let total = cc.vv.gameData.GetTotalFree();
        let rest = cc.vv.gameData.GetFreeTime();
        SlotsFacade.bottomCmp.ShowFreeModel(true,total-rest,total);
        await SlotsFacade.freeGame.enter(isReconnect);
        await SlotsFacade.delayTime(0.5);
    },

    /**
     * 进入普通游戏
     */
    async enterNormalGame() {
        SlotsFacade.bottomCmp.ShowFreeModel(false);
        SlotsFacade.mainPanel.showBg(0);
        SlotsFacade.soundMgr.playBgm(null, true);
        SlotsFacade.bottomCmp.node.getChildByName("totalBetBg").active = true;
        if(SlotsFacade.dm.isLastEndFree()) {
            let nTotal = cc.vv.gameData.GetGameTotalFreeWin()
            await new Promise(res=>{
                SlotsFacade.slots.ShowBottomWin(nTotal, nTotal,true, res);
            });
        }
    },

    /**
     * 收集能量
     */
    async collectEnergy() {
        if(cc.vv.gameData.GetTotalFree() > 0) {
            return;
        }
        await SlotsFacade.character.collectWild();
    },

    /**
     * 进入 pick game
     * @returns {Promise<void>}
     */
    async enterPickGame() {
        let pickData = SlotsFacade.dm.pickData;
        if(!pickData) {
            return;
        }

        await new Promise(res=>{
            SlotsFacade.pickGame.open(res);
        })

        let winCoin = SlotsFacade.dm.pickData.winCoin;
        let totalWin = winCoin;
        if(SlotsFacade.dm.getSpinData()) {
            totalWin += SlotsFacade.dm.GetGameWin();
        }
        SlotsFacade.dm.AddCoin(winCoin);
        await new Promise(res=>{
            SlotsFacade.slots.ShowBottomWin(winCoin, winCoin,true, res);
        });
    },

    /**
     * 进入转盘
     * @returns {Promise<void>}
     */
    async enterWheelGame() {
        SlotsFacade.topCmp.SetBackLobby(false);
        SlotsFacade.bottomCmp.ShowBtnsByState("moveing_1");
        let collectInfo = SlotsFacade.dm.collectInfo;
        if(collectInfo.state != 1) {
            return;
        }
        let scatterIdxs = SlotsFacade.dm.getCardsIndexs(SlotsFacade.dm.getGameCfg().scatterId);
        if(scatterIdxs.length>0) {
            await SlotsFacade.slots.playTriggerAni(scatterIdxs);
        }
        await new Promise(res=>{
            SlotsFacade.wheelGame.open(res);
        })
    }
})