cc.Class({
    extends: cc.Component,

    properties: {
        roundCount: 10,    // 圈数
        _canSpin:false,      // 是否可转
        _callBack:null,      // 完成后回调
        _resultIdx:0,       //

        panel:cc.Node,
        bg: cc.Node,
        board:cc.Node,
        btn_spin:cc.Node,
        arrow:cc.Node,
        collect_container:cc.Node,
        particle_start_pos:cc.Node,

        spine_super:sp.Skeleton,
        spine_8to10:sp.Skeleton,
        spine_win:sp.Skeleton,
    },

    _getRotation() {
        let ret = -this.roundCount * 360;
        let indexsAngle = [-22.5, -22.5-90, -22.5-45, -22.5-135];
        ret += indexsAngle[this._resultIdx-1];
        return ret;
    },

    onLoad() {
        this.btn_spin.on(cc.Node.EventType.TOUCH_END, ()=>{
            if(this._canSpin) {
                this._canSpin = false;
                SlotsFacade.soundMgr.playEffect("wheelspin");
                SlotsFacade.dm.reqSubGame({rtype:2});
                let btnSpine = this.btn_spin.getChildByName("spine").getComponent(sp.Skeleton);
                btnSpine.setAnimation(0, "Wheel_button_click", false);
            }
        }, this);
    },

    /**
     * @param msg
     */
    onWheelMsg(msg) {
        SlotsFacade.dm.collectInfo = msg.data.collectInfo;
        let freeInfo = msg.data.collectInfo.freeGameInfo;
        SlotsFacade.dm.SetFreeTime(freeInfo.totalCnt);
        SlotsFacade.dm.SetTotalFree(freeInfo.totalCnt);
        this._resultIdx = freeInfo.type;
        this._startWheel();
    },

    _reset() {
        this.board.angle = 0;
        for(let i=1; i<=4; i++) {
            this.board.getChildByName(`wheelNum${i}1`).active = true;
        }
        this.bg.active = true;
        this.spine_super.node.active = false;
        this.spine_8to10.node.active = false;
        this.spine_win.node.active = true;
        this.spine_win.setAnimation(0, "Wheel_idle", true);
        let btnSpine = this.btn_spin.getChildByName("spine").getComponent(sp.Skeleton);
        btnSpine.setAnimation(0, "Wheel_button_idle", true);
    },

    async _startWheel() {
        this.spine_win.node.active = false;
        SlotsFacade.soundMgr.playEffect("wheel");
        await new Promise((res)=> {
            cc.tween(this.board)
                .to(8, {angle:this._getRotation()}, { easing: 'quartInOut' })
                .call(()=> {
                    this.spine_win.node.active = true;
                    this.spine_win.setAnimation(0, "Wheel_win", true);
                    SlotsFacade.soundMgr.playEffect("wheelstop");
                    res();
                })
                .start();
        });
        await SlotsFacade.delayTime(2);
        await SlotsFacade.collectProgress.collectEnergy(this.particle_start_pos.convertToWorldSpaceAR(cc.v2(0, 0)));
        await this._processSuperMode();
        this._completeWheel();
    },

    /**
     * super game 动画逻辑处理
     * @returns {Promise<void>}
     * @private
     */
    async _processSuperMode() {
        let collectInfo = SlotsFacade.dm.collectInfo;
        if(collectInfo.state != 3) {
            return;
        }
        // 显示super mode 动画
        SlotsFacade.soundMgr.playEffect("supermode");
        this.spine_super.node.active = true;
        this.spine_super.setAnimation(0, "Supermode_intro", false);
        this.spine_super.addAnimation(0, "Supermode_idle", true);
        await SlotsFacade.delayTime(3);
        cc.tween(this.spine_super.node)
            .parallel(
                cc.tween().to(0.5, {scale:0.2}, {easing:"backIn"}),
                cc.tween().to(0.5, {position:this.spine_8to10.node.position}, {easing:"cubicIn"})
            )
            .call(()=>{
                this.spine_super.node.active = false;
            })
            .start();
        await SlotsFacade.delayTime(0.5);

        // 隐藏之前的倍数
        let freeInfo = collectInfo.freeGameInfo;
        this.board.getChildByName(`wheelNum${freeInfo.type}1`).active = false;

        // 显示8to10倍动画
        SlotsFacade.soundMgr.playEffect("collectIn");
        let skinName = ["Wins_8To10", "Spins_8To10", "Prizes_8To10", "Wilds_8To10"][freeInfo.type-1];
        this.spine_8to10.node.active = true;
        this.spine_8to10.setSkin(skinName);
        this.spine_8to10.setAnimation(0, "Wheel_8to10", false);
        this.spine_8to10.setCompleteListener(()=>{
            this.spine_8to10.setCompleteListener(null);
        })
        await SlotsFacade.delayTime(3);
    },

    /**
     * 旋转完毕
     * @param data
     * @returns {Promise<void>}
     * @private
     */
    async _completeWheel() {
        await this.close();
    },

    /**
     * 开始 开始转盘流程
     */
    async open(cb) {
        this._callBack = cb;
        await SlotsFacade.mainPanel.showSceneTransition(1);
        SlotsFacade.soundMgr.playBgm("bgbgm");
        this.bg.active = true;
        this.panel.active = true;
        this._reset();
        SlotsFacade.collectProgress.changeParent(this.collect_container);
        this._canSpin = true;
    },

    async close() {
        await SlotsFacade.mainPanel.showSceneTransition(1);
        let collectInfo = SlotsFacade.dm.collectInfo;
        if(collectInfo.state == 3) {
            for(let i=0; i<collectInfo.counts.length; i++) {
                if(collectInfo.counts[i] == 4) {
                    collectInfo.counts[i] = 0;
                }
            }
            SlotsFacade.collectProgress.updateProgress();
        }
        SlotsFacade.collectProgress.changeParent();
        this.panel.active = false;
        this.bg.active = false;
        if(this._callBack) {
            this._callBack();
        }
    },
});
