/**
 * @class NewKylin_GameData
 */
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {
        pickData  : null,
        collectInfo: null,
    },

    init(deskInfo,gameId,gameJackpot) {
        this.pickData = deskInfo.jackpotGame;
        this.collectInfo = deskInfo.collectInfo;
        this._super(deskInfo,gameId,gameJackpot);
    },

    //注册msg
    RegisterMsg(){
        this._super()
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, this.onResp, this);
    },
    UnregisterMsg(){
        this._super()
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, this.onResp, false, this);
    },

    OnRcvNetSpine:function(msg){
        if(msg.code == 200){
            this.pickData = msg.jackpotGame;
            this.collectInfo = msg.collectInfo;
        }
        this._super(msg);
    },

    getSpinData() {
        return this._gameInfo;
    },

    /**
     * 是否可以收集
     * @returns {boolean}
     */
    canCollect() {
        return this.GetBetIdx() >= this.getDeskInfo().needBet;
    },

    ///////////////////////子游戏请求//////////////////////////////
    /**
     * 请求子游戏数据51
     * @param param
     */
    reqSubGame(param) {
        let req = {
            c:MsgId.SLOT_SUBGAME_DATA,
            gameid:this._gameId,
            data:param
        };
        cc.vv.NetManager.send(req, true);
    },

    onResp(msg){
        if(msg.data.rtype == 1){
            SlotsFacade.pickGame.onPickMsg(msg);
        } else if(msg.data.rtype == 2){
            SlotsFacade.wheelGame.onWheelMsg(msg);
        }
    },
    ///////////////////////免费相关//////////////////////////////
    /**
     * 是否有免费
     * @returns {boolean}
     */
    hasFree() {
        return this.GetFreeTime() > 0;
    },

    /**
     * 是否触发免费
     */
    isTriggerFree() {
        return this.isFistTriggerFree();
    },

    /**
     * 是否是第一次触发免费
     */
    isFistTriggerFree() {
        return this.hasFree() && this.GetFreeTime() == this.GetTotalFree();
    },

    /**
     * 是否是最后一轮免费(旋转完成)
     */
    isLastEndFree() {
        return this.GetFreeTime() == 0 && this.GetTotalFree() > 0;
    },

    /**
     * 获取指定id的下标
     */
    getCardsIndexs(id) {
        if(!this._gameInfo) {
            return [];
        }
        let ret = [];
        let cards = this._gameInfo.resultCards;
        for(let i=0; i<cards.length; i++) {
            if(id == cards[i]) {
                ret.push(i+1);
            }
        }
        return ret;
    },
});
