cc.Class({
    extends: cc.Component,

    properties: {
        title:cc.Node,
        dialog_node:cc.Node,
        wild_node:cc.Node,
        spine_glow:sp.Skeleton,
        collect_coin_particle:cc.ParticleSystem,
        spineBottom:sp.Skeleton,    // 加金币时底部文本特效
        _isEnter:false,
        _roundItems:null,
        _currFreeType:1,
    },

    onLoad() {
        this._bottomLabel = cc.find("winBg/lbl_winNum_nor", SlotsFacade.bottomCmp.node);
        let bottomPos = this._bottomLabel.convertToWorldSpaceAR(cc.v2(0,0));
        bottomPos = SlotsFacade.mainPanel.top_node.convertToNodeSpaceAR(bottomPos);
        this.spineBottom.node.position = bottomPos;
        this._symbolTemplate = SlotsFacade.dm.GetPrefabByName(SlotsFacade.dm.getGameCfg().symbolPrefab);
        this._symbolTemplate.optimizationPolicy = cc.Prefab.OptimizationPolicy.MULTI_INSTANCE;
        this.title.active = false;
        this.dialog_node.active = false;
        this._roundItems = [[],[],[],[]];
        for(let i=0; i<4; i++) {
            for(let j=0; j<10; j++) {
                this._roundItems[i].push(cc.find(`items${i+1}/round${j+1}`, this.node));
            }
        }
    },

    /**
     * 显示标题
     * @private
     */
    _showTitle(visible, type, isSuper) {
        visible = visible || false;
        this.title.active = visible;
        if(visible) {
            type = type || 1;
            let imgCmp = this.title.getChildByName("label").getComponent("ImgSwitchCmp");
            if(isSuper) {
                imgCmp.setIndex(4 + type - 1);
            } else {
                imgCmp.setIndex(type - 1);
            }
        }
    },

    /**
     * 显示局数信息
     * @private
     */
    _showRoundInfo() {
        let cfg = SlotsFacade.dm.getGameCfg();
        let collectInfo = SlotsFacade.dm.collectInfo;
        let freeType = collectInfo.freeGameInfo.type;
        this._currFreeType = freeType;
        this._showTitle(true, freeType, collectInfo.state == 3);
        let roundNode = this.node.getChildByName(`items${freeType}`);
        roundNode.active = true;

        let items = this._roundItems[freeType - 1];
        let coins = collectInfo.freeGameInfo.coins;
        let useCnt = collectInfo.freeGameInfo.useCnt;
        let mults = collectInfo.freeGameInfo.mults;
        for(let i=0; i<items.length; i++) {
            let item = items[i];
            if(i >= coins.length) {
                item.active = false;
            }else {
                item.active = true;
                let label = item.getChildByName("label").getComponent(cc.Label);
                if(coins[i] > 0) {
                    label.string = Global.FormatNumToComma(coins[i]);
                }else {
                    label.string = "";
                }
                if(freeType == cfg.FreeGameType.Win || freeType == cfg.FreeGameType.Spin) {
                    // 局数标题
                    let titleLabel = item.getChildByName("title").getComponent("ImgSwitchCmp");
                    titleLabel.setIndex(i);
                    // 局数数字
                    let roundSpine = item.getChildByName("spine_numb").getComponent(sp.Skeleton);
                    if(useCnt < 1) {
                        if(freeType == cfg.FreeGameType.Win) {
                            roundSpine.node.active = i<mults.length-1;
                        }else {
                            roundSpine.node.active = i<4;
                        }
                    }else {
                        roundSpine.node.active = true;
                    }

                    roundSpine.setSkin(`${mults[i]}x`);
                    if(useCnt>i) {
                        roundSpine.setAnimation(0, "Num_grey_jingzhen", false);
                    }else {
                        roundSpine.setAnimation(0, "Num_jingzhen", false);
                    }
                } else {
                    // 设置局数数字
                    let roundLabel = item.getChildByName("round_label").getComponent("ImgSwitchCmp");
                    roundLabel.setIndex(i);
                    if(useCnt>i) {
                        roundLabel.showSpriteByName(`${i+1}spin2`);
                    }else {
                        roundLabel.showSpriteByName(`${i+1}spin1`);
                    }
                    // 设置箱子金币
                    if(freeType == cfg.FreeGameType.Prize) {
                        let label_prize = item.getChildByName("label_prize").getComponent(cc.Label);
                        label_prize.string = Global.convertNumToShort(collectInfo.freeGameInfo.prizes[i]);
                    }
                }
            }
        }
    },

    /**
     * 显示免费选择倍数框
     * @returns {Promise<void>}
     * @private
     */
    async _showFreeDialog() {
        let cfg = SlotsFacade.dm.getGameCfg();
        let collectInfo = SlotsFacade.dm.collectInfo;
        let freeType = collectInfo.freeGameInfo.type;
        let isSuper = collectInfo.freeGameInfo.coins.length == 10;

        let panel = this.dialog_node;
        panel.scale = 1;
        panel.active = true;
        // 标题
        let title = panel.getChildByName("title").getComponent("ImgSwitchCmp");
        title.setIndex(freeType-1 + (isSuper?4:0));
        // 内容
        let contentNode = null;
        if(freeType == 1 || freeType == 2) {
            let multiple = collectInfo.freeGameInfo.mults[collectInfo.freeGameInfo.mults.length-1];
            contentNode = panel.getChildByName("content1");
            contentNode.active = true;
            // 初始化箱子
            for(let i=0; i<3; i++) {
                let box = contentNode.getChildByName(`box${i+1}`);
                let label = box.getChildByName("multiple").getComponent("ImgSwitchCmp");
                label.node.opacity = 0;
                label.node.active = false;
                let spine = box.getChildByName("spine").getComponent(sp.Skeleton);
                spine.node.active = true;
                spine.node.opacity = 0xff;
                spine.setAnimation(0, "FG_box_intro", false);
                spine.addAnimation(0, "FG_box_idle", true);
            }
            // 点击逻辑
            await new Promise(res=>{
                for(let i=0; i<3; i++) {
                    let box = contentNode.getChildByName(`box${i+1}`);
                    box.on(cc.Node.EventType.TOUCH_END, async ()=>{
                        SlotsFacade.soundMgr.playEffect("fgpick");
                        // 播放点击动画
                        box.getChildByName("spine").getComponent(sp.Skeleton).setAnimation(0, "FG_box_click", false);
                        await SlotsFacade.delayTime(0.6);
                        // 显示倍数
                        for(let j=0; j<3; j++) {
                            let item = contentNode.getChildByName(`box${j+1}`);
                            item.off(cc.Node.EventType.TOUCH_END);
                            let label = item.getChildByName("multiple").getComponent("ImgSwitchCmp");
                            label.node.active = true;
                            if(i == j) {
                                label.showSpriteByName(`${multiple}x1`);
                            }else {
                                label.showSpriteByName(`${[6,8,10][Math.floor(Math.random()*3)]}x2`);
                            }
                            cc.tween(label.node)
                                .to(0.5, {opacity:0xff})
                                .start();
                            let spine = item.getChildByName("spine").getComponent(sp.Skeleton);
                            cc.tween(spine.node)
                                .to(0.5, {opacity:0})
                                .start();
                        }
                        await SlotsFacade.delayTime(0.6);
                        // 倍数飞行到局数
                        SlotsFacade.soundMgr.playEffect("fgmult");
                        let flyLabel = cc.instantiate(box.getChildByName("multiple"));
                        flyLabel.position = panel.convertToNodeSpaceAR(box.convertToWorldSpaceAR(cc.v2(0,0)));
                        flyLabel.parent = panel;
                        if(freeType == cfg.FreeGameType.Win) {
                            let spineNum = this._roundItems[freeType-1][collectInfo.freeGameInfo.mults.length-1].getChildByName("spine_numb").getComponent(sp.Skeleton);
                            let endPos = spineNum.node.convertToWorldSpaceAR(cc.v2(0,0));
                            endPos = panel.convertToNodeSpaceAR(endPos);
                            cc.tween(flyLabel)
                                .to(0.5, {x:endPos.x, y:endPos.y})
                                .call(()=>{
                                    flyLabel.removeFromParent();
                                    spineNum.node.active = true;
                                    spineNum.setSkin(`${multiple}x`);
                                    spineNum.setAnimation(0, "Num_intro", false)
                                })
                                .start();
                        }else {
                            let spineNum = this._roundItems[freeType-1][4].getChildByName("spine_numb").getComponent(sp.Skeleton);
                            let endPos = spineNum.node.convertToWorldSpaceAR(cc.v2(0,0));
                            endPos = panel.convertToNodeSpaceAR(endPos);
                            cc.tween(flyLabel)
                                .to(0.5, {x:endPos.x, y:endPos.y})
                                .call(async ()=>{
                                    flyLabel.removeFromParent();
                                    for(let j=4; j<collectInfo.freeGameInfo.mults.length; j++) {
                                        let sn = this._roundItems[freeType-1][j].getChildByName("spine_numb").getComponent(sp.Skeleton);
                                        sn.node.active = true;
                                        sn.setSkin(`${multiple}x`);
                                        sn.setAnimation(0, "Num_intro", false)
                                        await SlotsFacade.delayTime(0.1);
                                    }
                                })
                                .start();
                        }
                        await SlotsFacade.delayTime(1);
                        res();
                    }, this)
                }

            })
        }else {
            contentNode = panel.getChildByName(`content${freeType}`);
            contentNode.active = true;
        }
        await new Promise(res=>{
            cc.tween(panel)
                .delay(1.5)
                .to(0.4, {scale:0}, {easing:"backIn"})
                .call(()=>{
                    contentNode.active = false;
                    panel.active = false;
                    res();
                })
                .start();
        });
    },

    /**
     * 点击开始旋转调用 还未获取服务器返回的当局消息
     * @returns {Promise<void>}
     */
    async startMove() {
        if(!this._isEnter) {
            return;
        }
        let cfg = SlotsFacade.dm.getGameCfg();
        let freeInfo = SlotsFacade.dm.collectInfo.freeGameInfo;
        if(freeInfo.type == cfg.FreeGameType.Win || freeInfo.type == cfg.FreeGameType.Spin) {
            // 播放局数状态动画
            let spineNumb = this._roundItems[freeInfo.type-1][freeInfo.useCnt].getChildByName("spine_numb").getComponent(sp.Skeleton);
            spineNumb.setAnimation(0, "Num_idle", true);
        }
    },

    /**
     * 收到spin消息调用
     * @returns {Promise<void>}
     */
    async onSpinMsg() {
        if(!this._isEnter) {
            return;
        }
        let cfg = SlotsFacade.dm.getGameCfg();
        let collectInfo = SlotsFacade.dm.collectInfo;
        let freeType = collectInfo.freeGameInfo.type;
        if(freeType != cfg.FreeGameType.Wild) {
            return;
        }
        await this.showRandomWild(collectInfo.freeGameInfo.currWilds);
    },

    /**
     * 旋转结束调用
     * @returns {Promise<void>}
     */
    async spinEnd() {
        if(!this._isEnter) {
            return;
        }
        this.removeWild();
    },

    async enter(isReconnect) {
        SlotsFacade.mainPanel.jackpot_node.active = false;
        SlotsFacade.character.hide();
        this._isEnter = true;
        this._showRoundInfo();
        if(SlotsFacade.dm.collectInfo.freeGameInfo.useCnt < 1) {
            await this._showFreeDialog();
        }
    },

    async exit() {
        SlotsFacade.mainPanel.jackpot_node.active = true;
        SlotsFacade.character.show();
        this._isEnter = false;
        this._showTitle(false);
        let roundNode = this.node.getChildByName(`items${this._currFreeType}`);
        roundNode.active = false;
    },

    // ##########随机wild 相关##########
    /**
     * 显示随机wild
     * @param idxs
     * @returns {Promise<void>}
     */
    async showRandomWild(idxs) {
        this.wild_node.active = true;
        for(let idx of idxs) {
            SlotsFacade.soundMgr.playEffect("wildin");
            let symbol = this.genAWildSymbol(idx);
            symbol.playWildAppear();
            await SlotsFacade.delayTime(0.7);
        }
        SlotsFacade.soundMgr.playEffect("wild_appear");
        await SlotsFacade.delayTime(0.5);
    },

    /**
     * 生成一个wild图标
     * @param {*} idx
     */
    genAWildSymbol(idx) {
        let cfg = SlotsFacade.dm.getGameCfg();
        let node = cc.instantiate(this._symbolTemplate)
        node.parent = this.wild_node;
        let scp = node.addComponent(cfg.scripts.Symbols)
        scp.SetSymbolReelIdx(0);
        scp.Init(0, this.node);
        scp.ShowById(cfg.wildId);
        let pos = SlotsFacade.slots.getIdxGlobalPos(idx);
        pos = this.wild_node.convertToNodeSpaceAR(pos);
        node.setPosition(pos);
        return scp;
    },
    /**
     * 移除wild
     */
    removeWild() {
        this.wild_node.active = false;
        this.wild_node.removeAllChildren();
    },

    // ############结算###########
    /**
     * 单局结算
     * @returns {Promise<void>}
     */
    async settlementRound() {
        let cfg = SlotsFacade.dm.getGameCfg();
        let collectInfo = SlotsFacade.dm.collectInfo;
        let freeInfo = collectInfo.freeGameInfo;
        let freeType = freeInfo.type;
        let isSuper = freeInfo.coins.length == 10;
        let useCnt = freeInfo.useCnt;
        if(useCnt < 1) {
            return;
        }
        let currRoundItem = this._roundItems[freeInfo.type-1][useCnt-1];
        let nWin = SlotsFacade.dm.GetGameWin();
        let hasBox = freeType == cfg.FreeGameType.Prize && freeInfo.currBoxs && freeInfo.currBoxs.length>0;
        if(nWin > 0 || hasBox) {
            let labelRollCmp = currRoundItem.getChildByName("label").getComponent("LabelRollCmp");
            // 显示当局金币
            if(nWin) {
                SlotsFacade.soundMgr.playEffect("win_a");
                await new Promise(res=>{
                    labelRollCmp.startRoll(0, nWin, 1.5, res);
                })
                SlotsFacade.soundMgr.stopEffectByName("win_a");
                SlotsFacade.soundMgr.playEffect("win_end");
            }
            // 乘以倍数
            if(freeType == cfg.FreeGameType.Win || freeType == cfg.FreeGameType.Spin) {
                SlotsFacade.soundMgr.playEffect("popupend");
                let spineNumb = currRoundItem.getChildByName("spine_numb").getComponent(sp.Skeleton);
                spineNumb.setAnimation(0, "Num_Mul", false);
                let spineNumbTrans = currRoundItem.getChildByName("spine_numb_trans").getComponent(sp.Skeleton);
                spineNumbTrans.node.active = true;
                spineNumbTrans.setAnimation(0, "Num_Mul_trans", false);
                spineNumbTrans.setCompleteListener(()=>{
                    spineNumbTrans.setCompleteListener(null);
                    spineNumbTrans.node.active = false;
                })
                await SlotsFacade.delayTime(1);
                labelRollCmp.label.string = Global.FormatNumToComma(freeInfo.coins[useCnt-1]);
            }else {
                let roundLabel = currRoundItem.getChildByName("round_label").getComponent("ImgSwitchCmp");
                roundLabel.showSpriteByName(`${freeInfo.useCnt}spin2`);
            }
            if(hasBox) {
                // 开箱子
                let currBoxs = freeInfo.currBoxs;
                let boxWin = 0;
                for(let i=0; i<currBoxs.length; i++) {
                    let boxVo = currBoxs[i];
                    let symbol = SlotsFacade.slots.GetSymbolByIdx(boxVo.idx);
                    symbol.openBox(boxVo.coin);
                    boxWin += boxVo.coin;
                }
                SlotsFacade.soundMgr.playEffect("repeatopen");
                if(currBoxs.length) {
                    await SlotsFacade.delayTime(2);
                    SlotsFacade.soundMgr.playEffect("win_a");
                    await new Promise(res=>{
                        labelRollCmp.startRoll(nWin, nWin+boxWin, 1.5, res);
                    })
                    SlotsFacade.soundMgr.stopEffectByName("win_a");
                    SlotsFacade.soundMgr.playEffect("win_end");
                }
            }
        }else {
            if(freeType == cfg.FreeGameType.Win || freeType == cfg.FreeGameType.Spin) {
                let spineNumb = currRoundItem.getChildByName("spine_numb").getComponent(sp.Skeleton);
                spineNumb.setAnimation(0, "Num_grey_jingzhen", false);
            }else {
                let roundLabel = currRoundItem.getChildByName("round_label").getComponent("ImgSwitchCmp");
                roundLabel.showSpriteByName(`${useCnt}spin2`);
            }
        }
    },

    /**
     * 总结算
     * @returns {Promise<void>}
     */
    async settlementTotal() {
        let collectInfo = SlotsFacade.dm.collectInfo;
        let freeInfo = collectInfo.freeGameInfo;
        let sum = freeInfo.winCoin - freeInfo.coins.reduce((a,b)=>{return a+b}, 0);
        for(let i=0; i<freeInfo.coins.length; i++) {
            let coin = freeInfo.coins[i];
            if(coin < 1) {
                continue;
            }
            let roundItem = this._roundItems[freeInfo.type-1][i];
            let pos = roundItem.convertToWorldSpaceAR(cc.v2(0, 0));
            // 显示光效
            this.spine_glow.node.position = this.node.convertToNodeSpaceAR(pos);
            this.spine_glow.node.active = true;
            this.spine_glow.setAnimation(0, "jiesuan_glow", false);
            // 移动粒子
            SlotsFacade.soundMgr.playEffect("wheelfly");
            let p = cc.instantiate(this.collect_coin_particle.node).getComponent(cc.ParticleSystem);
            p.node.active = true;
            p.node.parent = SlotsFacade.mainPanel.top_node;
            p.node.position = SlotsFacade.mainPanel.top_node.convertToNodeSpaceAR(pos);
            p.resetSystem();

            cc.tween(p.node)
                .to(0.5, {x:this.spineBottom.node.x, y:this.spineBottom.node.y})
                .call(()=>{
                    p.node.removeFromParent();
                })
                .start()
            await SlotsFacade.delayTime(0.5);
            this.spineBottom.node.active = true;
            this.spineBottom.setAnimation(0, "animation", false);
            // 更新金币
            this._bottomLabel.active = true;
            await new Promise(res=>{
                Global.doRoallNumEff(this._bottomLabel, sum, sum+coin, 0.3, res, null,0,true)
            })
            sum += coin;
        }
        await SlotsFacade.delayTime(0.5);
        this.spineBottom.node.active = true;
    }
});
