/**
 * 角色动画控制
 */
cc.Class({
    extends: cc.Component,

    properties: {
        role:sp.Skeleton,
        // ball:sp.Skeleton,
        // zhuzi_effect:sp.Skeleton,
        // fly_particle:cc.Node,
    },

    hide() {
        this.node.active = false;
    },

    show() {
        this.node.active = true;
    },

    /**
     * 收集wild
     */
    async collectWild() {
        return;
        let wildIdxs = SlotsFacade.dm.getCardsIndexs(SlotsFacade.dm.getGameCfg().wildId);
        if(wildIdxs.length < 1) {
            return;
        }
        let endPos = SlotsFacade.mainPanel.top_node.convertToNodeSpaceAR(this.getBallGlobalPos());
        SlotsFacade.soundMgr.playEffect("nmbrfly");
        for(let i=0; i<wildIdxs.length; i++) {
            let pos = SlotsFacade.slots.getIdxGlobalPos(wildIdxs[i]);
            let p = cc.instantiate(this.fly_particle).getComponent(cc.ParticleSystem);
            p.node.active = true;
            p.node.parent = SlotsFacade.mainPanel.top_node;
            p.node.position = p.node.parent.convertToNodeSpaceAR(pos);
            p.resetSystem();
            cc.tween(p.node)
                .to(0.5, {position:endPos})

                .call(()=>{
                    p.node.removeFromParent();
                })
                .start();
        }
        await SlotsFacade.delayTime(0.5);
        this.zhuzi_effect.node.active = true;
        this.zhuzi_effect.setAnimation(0, "zhuzi_collect", false);
        this.zhuzi_effect.setCompleteListener(()=>{
            this.zhuzi_effect.setCompleteListener(null);
            this.zhuzi_effect.node.active = false;
        });
    },

    /**
     * 获取龙珠的全局坐标
     * @returns {*}
     */
    getBallGlobalPos() {
        return this.ball.node.convertToWorldSpaceAR(cc.v2(0,0));
    },
});
