
/**
 * 收集进度
 * @class NewKylin_CollectProgress
 */
cc.Class({
    extends: cc.Component,

    properties: {
        lock_btn:cc.Node,
        spine_collect_lock:sp.Skeleton, // 能量条状态spine动画
        collect_track_particle:[cc.ParticleSystem], // 能量收集轨道粒子动画
        _stepItems:null,
        _isOpen:false,   // 是否打开收集
    },

    onLoad() {
        this._stepItems = [[], [], [], []];
        for(let i=0; i<this._stepItems.length; i++) {
            let item = cc.find(`type${i+1}`, this.node);
            for(let j=0; j<4; j++) {
                this._stepItems[i].push(item.getChildByName(`item${j+1}`));
            }
        }

        Global.registerEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED, ()=>{
            this.showCollect(false);
        },this);
        this.lock_btn.on(cc.Node.EventType.TOUCH_END, ()=>{
            if(!this._isOpen || this.node.parent == SlotsFacade.mainPanel.collect_progress_container) {
                this._openCollect();
            }
        }, this);
        this.updateProgress();
        this.showCollect(true);
    },

    /**
     * 初始化收集条
     * @private
     */
    updateProgress() {
        let collectInfo = SlotsFacade.dm.collectInfo;
        for(let i=0; i<this._stepItems.length; i++) {
            let count = collectInfo.counts[i];
            for(let j=0; j<4; j++) {
                let item = this._stepItems[i][j];
                let isCmp = count>j;
                item.getChildByName("icon").active = isCmp || j==3;
                item.getChildByName("effect").active = false;
            }
        }
    },

    /**
     * 打开收集
     */
    _openCollect() {
        // 如果已经打开收集 返回
        if(this._isOpen) {
            return;
        }
        // 如果在免费中 返回
        if(SlotsFacade.dm.hasFree()) {
            return;
        }
        // 如果spin不可点击 返回
        if(!SlotsFacade.bottomCmp.GetSpinBtnState()) {
            return;
        }
        // 自动模式不可点击 返回
        if(cc.vv.gameData.GetAutoModelTime() > 0) {
            return;
        }
        let betList = SlotsFacade.dm.GetBetMults();
        let needBet = SlotsFacade.dm.getDeskInfo().needBet;
        // 金币不足
        if(needBet > betList.length) {
            return;
        }
        SlotsFacade.dm.SetBetIdx(needBet);
        SlotsFacade.bottomCmp.ShowBetCoin();
        let nTotal = cc.vv.gameData.GetTotalBet()
        Global.dispatchEvent(cc.vv.gameData._EventId.SLOT_TOTALBET_UPDATED,nTotal)
    },

    /**
     * 显示收集界面
     * @param isInit
     */
    showCollect(isInit) {
        let boo = SlotsFacade.dm.canCollect();
        if(boo) {
            if(!this._isOpen) {
                if(isInit) {
                    this.spine_collect_lock.node.active = false;
                }else {
                    SlotsFacade.soundMgr.playEffect("repeatopen");
                    this.spine_collect_lock.node.active = true;
                    this.spine_collect_lock.setAnimation(0, "Betup_unlock", false);
                }
            }
        }else {
            this.spine_collect_lock.node.active = true;
            if(isInit) {
                this.spine_collect_lock.setAnimation(0, "Betup_lock", false);
            }else {
                if(this._isOpen) {
                    SlotsFacade.soundMgr.playEffect("lock");
                    this.spine_collect_lock.setAnimation(0, "Betup_lock_idle", false);
                    this.spine_collect_lock.addAnimation(0, "Betup_lock", false);
                }
            }
        }
        this._isOpen = boo;
    },

    /**
     * 收集能量
     * @param posStartGlobal
     */
    async collectEnergy(posStartGlobal) {
        if(!SlotsFacade.dm.canCollect()) {
            return;
        }
        let collectInfo = SlotsFacade.dm.collectInfo;
        let freeInfo = collectInfo.freeGameInfo;
        let count = collectInfo.counts[freeInfo.type-1];
        let item = this._stepItems[freeInfo.type-1][count-1];
        // 移动粒子
        SlotsFacade.soundMgr.playEffect("wheelfly");
        let p = this.collect_track_particle[freeInfo.type-1];
        p.node.position = this.node.convertToNodeSpaceAR(posStartGlobal);
        p.node.active = true;
        p.resetSystem();
        let endPos = this.node.convertToNodeSpaceAR(item.convertToWorldSpaceAR(cc.v2(0,0)))
        cc.tween(p.node)
            .to(0.5, {x:endPos.x, y:endPos.y})
            .call(()=>{
                p.node.active = false;
            })
            .start();
        await SlotsFacade.delayTime(0.5);
        // 显示珠子
        let icon = item.getChildByName("icon");
        icon.active = true;
        let effect = item.getChildByName("effect").getComponent(sp.Skeleton);
        effect.node.active = true;
        if(count == 4) {
            effect.setAnimation(0, "super_fire", false);
            icon.getComponent(sp.Skeleton).setAnimation(0, `super_${["wins","spins","awards","wilds"][freeInfo.type-1]}_1`, false);
        }else {
            effect.setAnimation(0, `S_${["wins","spins","prizes","wilds"][freeInfo.type-1]}`, false);
        }
        effect.setCompleteListener(()=>{
            effect.setCompleteListener(null);
            effect.node.active = false;
        })
        await SlotsFacade.delayTime(1);
    },

    /**
     * 改变父节点
     * @param parent
     */
    changeParent(parent) {
        parent = parent || SlotsFacade.mainPanel.collect_progress_container;
        this.node.parent = parent;
    },
});
