cc.Class({
    extends: cc.Component,

    properties: {
        panel:cc.Node,
        pickItems:[cc.Node],

        _canTouch:false,
        _callBack:null,
    },

    onLoad() {
        for(let i=0; i<this.pickItems.length; i++) {
            let item = this.pickItems[i];
            let cmp = item.addComponent("NewKylin_PickItem");
            cmp.init(i+1, this._pickItemHandler.bind(this));
        }
        this._reset();
    },

    _reset() {
        for(let i=0; i<this.pickItems.length; i++) {
            let item = this.pickItems[i];
            let cmp = item.getComponent("NewKylin_PickItem");
            cmp.reset();
        }
    },

    /**
     * pick item 点击回调
     * @param id
     * @private
     */
    _pickItemHandler(id) {
        if(!this._canTouch) {
            return;
        }
        let pickData = SlotsFacade.dm.pickData;
        if(pickData.items[id-1].isOpen) {
            console.log(`Error:${id} 已经打开`)
            return;
        }
        SlotsFacade.soundMgr.playEffect("bgpick");
        this._canTouch = false;
        SlotsFacade.dm.reqSubGame({rtype:1, choiceId:id});
    },

    /**
     * 选择结果返回
     */
    onPickMsg(msg) {
        let pickData = msg.data.jackpotGame;
        SlotsFacade.dm.pickData = pickData;
        let choiceId = msg.data.choiceId;
        let pickItemCmp = this.pickItems[choiceId-1].getComponent("NewKylin_PickItem");
        let jackpotId = pickData.items[choiceId-1].jackpotId;
        pickItemCmp.setState(3, jackpotId);

        if(pickData.isEnd) {
            this._canTouch = false;
            this._settlement(jackpotId);
        }else {
            this._canTouch = true;
        }
    },

    async _settlement(jackpotId) {
        SlotsFacade.soundMgr.playEffect("coinsure");
        let itemsRet = SlotsFacade.dm.pickData.items;
        // 播放中奖jackpot 图标
        for(let i=0; i<itemsRet.length; i++) {
            let item = itemsRet[i];
            if(item.jackpotId == jackpotId) {
                let cmp = this.pickItems[i].getComponent("NewKylin_PickItem");
                cmp.playWin();
            }
        }
        await SlotsFacade.delayTime(1);
        // 播放剩余jackpot 图标
        for(let i=0; i<itemsRet.length; i++) {
            let item = itemsRet[i];
            if(!item.isOpen) {
                let cmp = this.pickItems[i].getComponent("NewKylin_PickItem");
                cmp.setState(2, item.jackpotId)
            }
        }
        await SlotsFacade.delayTime(1.5);
        // 弹窗奖励
        await SlotsFacade.popup.showWinJpGold(SlotsFacade.dm.pickData.winCoin, jackpotId);
        this.close();
    },
    
    _initBag() {
        let jpData = SlotsFacade.dm.jackpotGame;
        for(let i=0; i<jpData.choiceIdxs.length; i++) {
            let idx = jpData.choiceIdxs[i];
            let itemType = jpData.choiceItems[i];
            let bag = this._bagList[idx-1];
            bag.setItemType(itemType);
        }
    },

    /**
     * 重连时需要初始化点击过的item
     * @private
     */
    _initItems() {
        let pickData = SlotsFacade.dm.pickData;
        if(pickData) {
            this.scheduleOnce(()=>{
                for(let i=0; i<pickData.items.length; i++) {
                    let itemVo = pickData.items[i];
                    if(itemVo.isOpen) {
                        let item = this.pickItems[i].getComponent("NewKylin_PickItem");
                        item.setState(3, pickData.items[i].jackpotId)
                    }
                }
            })
        }
    },

    async open(cb) {
        this._callBack = cb;
        SlotsFacade.soundMgr.playEffect("triggering");
        await SlotsFacade.mainPanel.showSceneTransition(2);
        SlotsFacade.soundMgr.playBgm("bgbgm");
        this.panel.active = true;
        this._reset();
        this._canTouch = true;
        this._initItems();
    },

    async close() {
        await SlotsFacade.mainPanel.showSceneTransition(2);
        SlotsFacade.soundMgr.playBgm(null, true);
        this.panel.active = false;
        if(SlotsFacade.dm.hasFree()) {
            SlotsFacade.soundMgr.playFreeBgm();
        }else {
            Global.SlotsSoundMgr.stopBgm();
            SlotsFacade.soundMgr.playBgm();
        }
        if(this._callBack) {
            this._callBack();
        }
    },
});
