/**
 * 弹窗管理器
 * @class NewKylin_Popup
 */
cc.Class({
    extends: cc.Component,

    properties:{
        bg:cc.Node
    },

    onLoad() {

    },

    showBg(boo) {
        this.bg.active = boo;
    },

    /**
     * 显示赢取金币
     * @param {number} goldNumb 
     */
    async showWinGold(goldNumb) {
        SlotsFacade.soundMgr.playEffect("bell");
        this.showBg(true);
        let panel = this.node.getChildByName("panel_win_coin");
        panel.active = true;
        panel.scale = 0;
        panel.getChildByName("label").getComponent("LabelRollCmp").startRoll(0, goldNumb);
        cc.tween(panel)
            .to(0.5, {scale:1}, {easing:"backOut"})
            .start()
        await SlotsFacade.delayTime(0.5);
        let okBtn = panel.getChildByName("btn_ok");
        await new Promise(res=>{
            let handler = ()=>{
                SlotsFacade.soundMgr.playEffect("popup_out");
                okBtn.off(cc.Node.EventType.TOUCH_END, handler);
                cc.tween(panel)
                    .to(0.5, {scale:0}, {easing:"backIn"})
                    .call(()=>{
                        this.showBg(false);
                        panel.active = false;
                        res();
                    })
                    .start();
            };
            okBtn.on(cc.Node.EventType.TOUCH_END, handler);
        });
    },

    /**
     * 显示赢取金币
     * @param {number} goldNumb 
     * @param {number} jpType 1~4 mini~grand
     */
    async showWinJpGold(goldNumb, jpType) {
        if(!jpType) {
            jpType = 1;
        }
        SlotsFacade.soundMgr.playEffect("jpwin");
        this.showBg(true);
        let panel = this.node.getChildByName("panel_win_jp_coin");
        panel.active = true;
        panel.scale = 0;
        panel.getChildByName("label").getComponent("LabelRollCmp").startRoll(0, goldNumb);

        let jp_icon = panel.getChildByName("jp_icon").getComponent("ImgSwitchCmp");
        jp_icon.setIndex(jpType-1);
        cc.tween(panel)
            .to(0.5, {scale:1}, {easing:"backOut"})
            .start()
        await SlotsFacade.delayTime(0.5);
        let okBtn = panel.getChildByName("btn_ok");
        await new Promise(res=>{
            let handler = ()=>{
                okBtn.off(cc.Node.EventType.TOUCH_END, handler);
                SlotsFacade.soundMgr.playEffect("popup_out");
                cc.tween(panel)
                    .to(0.5, {scale:0}, {easing:"backIn"})
                    .call(()=>{
                        this.showBg(false);
                        panel.active = false;
                        res();
                    })
                    .start();
            };
            okBtn.on(cc.Node.EventType.TOUCH_END, handler);
        });
    },
 })